local S = {}

S.guides = {
    { name = 'First Steps', group = 'Custom', desc = 'What a new Relaunch character already has, where the custom NPCs are, and how to get from level 1 into the Hunting League. Source: https://ffxi-legendary.com/getting-started/first-steps/', steps = { { title = 'Before you start', note = '• Install the client including xiloader.exe, then set the launcher\'s IP and ports as described on the Connect to the Server page.' }, { title = '1. The hub: Purgonorgo Isle', note = '• All custom NPCs stand on one island plaza, Purgonorgo Isle; reach it with !hub (aliases: !leaf, !lib).\n• Travel/setup: Home Point crystal, Warpman, Survival Guide.\n• Economy: Gil Exchange, Sparks Exchange, Race Changer, Title Broker, Mystery Mog, Cosmetic Shop, Casino, Daily and Hunt boards, Unity, Chocobo Derby.\n• Endgame: Apex Trials, Prime Armory, Relic Forge, Colosseum, Endless Tower, the Gauntlet, Infamy/HTBF/Voidwatch vendors, Augment Moogle and Sage, mastery trainers, Cross-Job Trainers, combat Test Dummy.' }, { title = '2. Granted at character creation', note = '• No setup NPC is needed; everything below is applied automatically.\n• All weapon skills and job spells (Trusts excluded); combat and magic skills capped to your level.\n• Trusts: Shantotto, Kupipi, Trion, Tenzen; others come from killing specific NMs.\n• About 4,000 key items.\n• All story missions done (every nation plus RoZ/CoP/ToAU/WotG/SoA/RoV); nation rank 10.\n• All maps, outpost warps (Tu\'Lia and Tavnazia included), homepoints, survival guides.\n• Full Mog Wardrobes; pet attachments for pet jobs.\n• 25 Hunt Marks.\n• Legendary Ring (Rare/Ex, all jobs): faster EXP and Capacity gain, Auto-Reraise, extra movement speed, no EXP loss on death.\n• Free Chocobo Shirt, Destrier Beret and Echad Ring from the Welcome Moogle at !hub.' }, { title = '3. Level to 99', note = '• Every job and subjob is unlocked; mob EXP is 3x, and books and RoE are also 3x.\n• !expcamp lists 22 level-banded camps (La Theine Plateau early, Kamihr Drifts at 95-99); !expcamp 4 warps to camp 4.\n• !warp opens a travel menu.' }, { title = '4. At 99: Hunting League', note = '• Type !hunt to warp to Escha ZiTah beside the Hunt Hub and Spawner NPCs.\n• The Hunting League has 5 ranks: kill NMs for Hunt Marks, spend marks on rank unlocks and reward-shop gear. Its NMs are level 99.\n• Talk to Hunt: Hub to check rank and marks.\n• Talk to Hunt: Spawner to pop a Rank I NM (Leaping Lizzy, Valkurm Emperor or Tom Tit Tat).\n• Each kill pays 15 Hunt Marks.\n• At 150 marks, return to Hunt: Hub and unlock Rank II.' }, { title = 'Summary', note = '• !hub, then the Welcome Moogle for starter gear.\n• !expcamp to level to 99.\n• !hunt to begin the Hunting League.\n• Page last updated 2026-09-01.' } } },
    { name = 'Your First Session', group = 'Custom', desc = 'The basic play loop after First Steps: earning and spending Hunt Marks at Escha ZiTah, plus login rewards, weekly boards and key commands. Source: https://ffxi-legendary.com/getting-started/your-session/', steps = { { title = 'Core idea', note = '• Hunt Marks are the main currency: earn them killing Hunting League NMs, spend them on seals, gear and rank unlocks.' }, { title = 'First 30 minutes at Escha ZiTah', note = '• Cast !buff first: Refresh, Regen, Regain and the zone\'s regional buff (Signet/Sanction/Sigil/Ionis). Recast when it drops or after zoning.\n• Talk to Hunt: Hub for your rank, mark balance and the reward shop (!marks shows the balance).\n• Talk to Hunt: Spawner to pop a Rank I NM (Leaping Lizzy, Valkurm Emperor, Tom Tit Tat); it spawns in front of you with no cooldown.\n• Get the kill credit: 15 marks per Rank I kill; your first ever kill adds +50 (First Hunt).\n• At the Hub, turn marks into Seals and spend them at the Escha ZiTah Armor and Weapons vendors (see Gear Vendors).\n• Unlock Rank II at the Hub for 150 marks; per-kill pay rises from 15 at Rank I to 100 at Rank 5.\n• !tier shows your tier, available NMs and rank-up requirements.\n• Rank I NMs are stronger than retail versions.' }, { title = 'Login and milestone rewards', note = '• Character creation: 25 Hunt Marks and a Legendary Ring (Rare/Ex).\n• First login each UTC day: +50.\n• Login streaks: 7 days +75, 14 days +200, 21 days +400, 30 days +750; missing a UTC day resets the streak.\n• NM kills: 1st +50 (First Hunt), 10th +100 (Ten Hunts In), 100th +300 (Centennial Hunter), 1,000th +1000 (Hero Among Heroes).\n• More milestones exist (first kill per tier, lifetime marks, Infamy); !achievements lists all.\n• Achievement titles can be shown with /title.' }, { title = 'Weekly and daily boards', note = '• Weekly Hunt Board: 5 objectives per week for bonus marks and a lifetime Weekly Hunter count; check with !weekly.\n• Featured Hunts: one NM per tier each week pays 2x base marks on your first kill that week; check with !featured.\n• Daily Board: lighter objectives, reset daily.\n• Hades: 5 daily errands for Soul Shards, plus 6 weekend stalls (Steel, Mail, Gild, Crate, Trusts, Cosmetics); Crate currency is banked on Hold and forges use it first; check with !hades.\n• Resets: daily 00:00 UTC, weekly Monday 00:00 UTC.' }, { title = 'Key commands', note = '• !hunt: warp to Escha ZiTah.\n• !buff: Refresh/Regen/Regain plus regional buff.\n• !marks: spendable and lifetime Hunt Marks.\n• !tier: current tier and rank-up needs.\n• !progress: one-screen summary of all systems.\n• !nms: NM Encyclopedia (killed vs remaining).\n• !achievements: all milestones.\n• !week / !weekly: weekly objectives.\n• !hades: today\'s Hades errands.\n• !featured: this week\'s 2x hunts.\n• !lfg: server-wide group request.\n• !who: online players ranked by tier.\n• !help: full command list.' }, { title = 'Later systems', note = '• Ascension (Prestige): reach Hunting League Legend, clear the Trial and pay marks for permanent per-job bonuses; nothing is wiped.\n• Job Rebirth is the separate system that resets a mastered job to level 1.\n• Also: Gear Guide, HNM Kings, Hunter\'s Guild.\n• Each character has a public profile with a recommended next step, listed after its first stats sync.\n• Page last updated 2026-09-11.' } } },
    { name = 'The 1–99 Checklist', group = 'Custom', desc = 'An ordered to-do list taking a new character from creation to level 99 and reforged AF/Relic/Empyrean gear. Source: https://ffxi-legendary.com/getting-started/leveling/', steps = { { title = '0. Wait for the grants', note = '• On creation the server grants all job spells (not Trusts), weapon skills, traits, skills and key items; it takes a few minutes and shows …downloading data… at the top.\n• Do not zone until the scrolling text stops, or the grant may be interrupted.\n• You start with four Trusts; the rest come from content.' }, { title = '1. Activate Records of Eminence', note = '• Go to the Eternal Flame in Western Adoulin near the Mog House, activate RoE and set objectives; it then pays EXP, Sparks and Unity Accolades as you play.' }, { title = '2. Gobbie Dial', note = '• Take the free daily roll at the Gobbie Dial NPC.' }, { title = '3. Settings', note = '• Configure auto inventory sort, chat filters and other preferences.' }, { title = '4. Go to the hub', note = '• Type !hub to reach Purgonorgo Isle, where all custom NPCs are.' }, { title = '5. Choose main and sub job', note = '• Use the Nomad Moogle at the !hub landing; all jobs and subjobs are unlocked and the subjob levels by itself.' }, { title = '6. Adventuring Fellow', note = '• Talk to the Fellow officer to spend points and choose your Fellow\'s role.' }, { title = '7. Starter gear', note = '• !ah: Auction House stocked with leveling gear at fixed prices.\n• !shop: optional buys, including rare/ex gear.\n• For gil, the Me Like Gil NPC in !hub converts Sparks of Eminence and other currencies.' }, { title = '8. Level to 99', note = '• Mob EXP is 3x.\n• Travel via the Survival Guide in !hub or use !expcamp: 22 camps from La Theine Plateau (10-25) to Kamihr Drifts (95-99); !expcamp <#> warps.\n• Use !buff (Refresh/Regen/Regain plus regional buff) and recast after it drops or you zone.' }, { title = '9. Level 50 and first 99 rewards', note = '• At 50, the Welcome Moogle in !hub opens a 1,000 gil shop; each item has two fixed augments and only gear for your current job is shown.\n• At your first 99, claim up to 48 free augment catalysts from the Commemoration Moogle in !hub; augmenting unlocks at 99.\n• Catalyst picks are final, character-bound and non-tradable; plan your augments first (see Augmenting Guide).' }, { title = '10. Gear up at 99', note = '• Use !shop to reforge AF/Relic/Empyrean to iLvl 109 for free.\n• Use the Reforge system to take them to iLvl 119.\n• Fill other slots from the Gear Guide and Hunting League Gear Vendors.\n• Next: Tier 1 Unity NMs (first iLvl 119 gear source), the Hunting League, and Your First Session.\n• Page last updated 2026-09-01.' } } },
    { name = 'Achieving Your First 99', group = 'Custom', desc = 'Roadmap from level 1 to a first 99, then one suggested post-99 order through gear, Hunting League, Affinities, Unity, Trust slots, HTBFs and Ambuscade. Source: https://ffxi-legendary.com/getting-started/progression-guide/', steps = { { title = 'Useful commands', note = '• !expcamp: list leveling camps; !expcamp 4 warps to one.\n• !hub: warp to Purgonorgo Isle (also !leaf, !lib).\n• !ah: Auction House from anywhere.\n• !autojp / !automerits: spend all unspent Job Points / Merit Points.\n• !buff: regional buff (Signet/Sanction/Sigil) for EXP bonus and Refresh.\n• !fellow: summon your Adventuring Fellow.\n• !home: warp to your home point.\n• !shop: server shop selling EXP/Capacity rings; reforged AF/Relic/Empyrean are free there.\n• !warpty: pull all online party members to the leader.' }, { title = 'Step 1 — Already set up', note = '• New characters get all jobs and subjobs, all weapon skills and job spells, capped skills, Trusts Shantotto/Kupipi/Trion/Tenzen, ~4,000 key items, all missions, all maps and warps, full wardrobes, a starter gear kit, 25 Hunt Marks and the Legendary Ring.\n• More Trusts drop from specific NMs.' }, { title = 'Step 2 — Level to 99', note = '• Mob EXP is 3x; !expcamp offers 22 camps, La Theine Plateau (10-25) to Kamihr Drifts (95-99).\n• Set a subjob; it earns 25% of your main job\'s EXP.\n• Activate Records of Eminence.\n• For bonus EXP on listed targets, pick up a Fields/Grounds of Valor page at a Field Manual or Grounds Tome.\n• Buy EXP and Capacity rings in !shop.\n• Use !buff in each zone.\n• The Eminence Broker in !hub buys Sparks, Unity Accolades, Job Points and Hunt Marks for gil.\n• !ah sells leveling gear at fixed level-bracket prices.\n• Reaching 50 unlocks the Welcome Moogle shop in !hub: items carrying two fixed augments, 1,000 gil each.' }, { title = 'Step 3a — Right after 99', note = '• Get free iLvl 109 AF/Relic/Empyrean from !shop.\n• Pick 48 augment catalysts (one time) from the Commemoration Moogle in !hub.' }, { title = 'Step 3b — First weapon', note = '• Use !hunt, then trade Hunt Marks at the Seals NPC for Beastmens Medals (5 marks each).\n• Bronze-tier weapons usually run 12 medals (60 marks); 25 starting marks plus the 50 daily login usually covers it.' }, { title = 'Step 3c — Rank I and Rank III', note = '• Rank I NMs (Leaping Lizzy, Valkurm Emperor, Tom Tit Tat) pay 15 marks; the first kill of each unique NM pays double, so kill each once.\n• The weekly Featured Hunt (!featured) pays 2x base on the first kill of the week.\n• Silver-tier weapons usually run 25 Kindreds Medals at 15 marks each (375 marks).\n• Rank II costs 150 marks and Rank III (Elite) 650; budget about 1,175 marks for Silver weapon plus Rank III.\n• Other mark sources: Hunter\'s Guild, Game Master waves.' }, { title = 'Step 3d — Reforge armor', note = '• Collect base and +1 pieces, then +2 in key slots; Empyrean +2 is a good early defensive/offensive mix for many jobs.\n• Build TP, defensive and weapon-skill sets suited to your job.\n• Check the Reforge page on this site, not retail sources, for Legendary-specific piece sources.' }, { title = 'Step 3e — Augments', note = '• See the Augmenting Guide and Augment Moogle page, or farm Augment Dungeons.\n• Early priorities: Haste, Accuracy/Magic Accuracy, Store TP, Damage Taken, Refresh, Fast Cast; later weapon-skill damage and multi-attack.' }, { title = 'Step 3f — Affinities and Unity', note = '• 25 Affinity NMs are always up; 11 of them register a Sage affinity.\n• !affinitynm lists them; !affinitynm <number|name> warps (1-25).\n• Each registration needs Hunting League Rank 3, the trophy and 250 marks (2,750 for all 11).\n• Unity: Tier II opens once every Tier I Unity NM is cleared.\n• Listed 119 weapons have a 5% drop; get the +1 by trading the base weapon at the Unity board.\n• Tier III is usually group content at this gear level but is not locked. See Unity Concord.' }, { title = 'Step 3g — Fourth Trust slot', note = '• You start with 2 slots.\n• Slot 3: get your Adventuring Fellow to level 100, or complete one Job Rebirth.\n• Slot 4: Voidwatch Tier 5+ plus clears in three different strata.\n• Suggested route: Crimson to Tier 5, then one Indigo and one Jade clear; easy rifts at North Gustaberg, Valkurm Dunes, Jugner Forest.' }, { title = 'Step 3h — Master the job, unlock HTBFs', note = '• On the job you enter with: 2,100 Job Points spent and all 11 Sage affinities registered.\n• Buy Phantom Gems from the Phantom Gems NPC in !hub.\n• !capacity is the quick Capacity Point camp.\n• HTBF Tier I allows 2 Trusts, Tier II allows 3.' }, { title = 'Step 3i — Final Proving', note = '• After one HTBF win at both Tier I and Tier II, the Phantom Gems NPC offers Final Proving.\n• Final Proving is a one-time Garuda fight; a win is credited as your Tier III clear and unlocks the full Tier III battlefield list.' }, { title = 'Step 3j — Ambuscade', note = '• Requires one HNM King kill (Fafnir/Nidhogg have retail spawns; Affinity copies also count if the Tome accepts them).\n• Requires one HTBF clear at Tier I, II and III (Final Proving counts for III).\n• Farm Hallmarks for 119 armor and a final Ambuscade weapon.\n• On that final weapon, normal weapon skills cap at 99,999 and its linked weapon skill (e.g. Savage Blade on Naegling, Blade: Ku on Gokotai) caps at 149,999.' }, { title = 'Step 4 — Other systems', note = '• Ascension/Prestige: at Hunting League Legend, a Trial plus marks; no wipe.\n• Job Rebirth: after mastering a job (99 + 2,100 JP); resets it to level 1.\n• Weapon Journey: Ambuscade, REMA, Aeonic, Prime.\n• Also later Unity NM tiers and Dynamis Divergence.\n• Page last updated 2026-09-01.' } } },
    { name = 'Augmenting: Start Here', group = 'Custom', desc = 'Beginner walkthrough of the augment system: banking catalysts, stamping stats onto gear at the Augment Moogle, how tiers set roll size, and how to reroll or crystalize. Source: https://ffxi-legendary.com/progression/augmenting-guide/', steps = { { title = 'What augmenting does', note = '• Each catalyst corresponds to one stat bonus (augment); any gear piece holds up to 5 augment lines.\n• Catalysts are stored in your Arcane Bank, used at the Augment Moogle on Purgonorgo Isle.\n• Repeating the same catalyst stacks that stat (5 Attack catalysts = 5 Attack lines on one item).\n• 142 catalysts exist, and all of them are usable at every Augment Tier; tier only changes roll strength.' }, { title = 'Your first augment', note = '• Farm catalysts: each one drops (~10% per kill) from a single assigned monster and goes to your Arcane Bank automatically; they can no longer be bought with gil.\n• Example: the Attack catalyst is Black Tiger Hide, dropped by Uleguerand Tiger (around level 60); collect 5.\n• Carry 10,000 gil, the flat fee per trade regardless of catalyst count.\n• Check your stored catalysts anywhere with !catalysts.\n• On Purgonorgo Isle, find the Augment Moogle / Arcane Augmenter among the moogles.\n• Pick Build an augment, choose up to 5 banked catalysts, then trade the gear; review the preview.\n• Confirm to pay 10,000 gil and receive the augmented gear back.\n• The examine window may show wrong or negative numbers on augmented gear; use !augstats for real values and !getstats offensive / defensive / base for gear totals.' }, { title = 'Augment Tiers and roll bands', note = '• Each line is rolled within your tier\'s band (scale 0–31); a new character is Tier 0 and cannot augment.\n• T1 (0–5): reach level 99 on any job.\n• T2 (6–11): defeat all 3 Rank 2 Hunt NMs and promote to Hunting League Rank 3.\n• T3 (12–17): defeat all 3 Rank 3 Hunt NMs, clear Voidspire floor 10, and Wave Master Easy/Normal/Hard.\n• T4 (18–24): defeat all 3 Rank 4 Hunt NMs, clear one full Dynamis - Divergence city, and Wave Master Insane.\n• T5 (25–31): defeat Maat\'s Echo (!warp > Activities).\n• Tiers must be cleared in sequence; your tier is the highest consecutive step done.\n• Example: Attack goes from +2 per slot at T1 up to +64 per slot at a top T5 roll (+320 on 5 slots).\n• Re-augment after each tier-up; every roll in a higher tier exceeds every roll in a lower one. Re-trade within a tier to chase the band\'s top.\n• Trust summon counts use a separate ladder (Unity Concord accolades, Voidwatch rift tiers, Adventuring Fellow level).' }, { title = 'Raising your rolls', note = '• Sage Mastery rank 1–5: adds +1 to your roll floor per rank and raises crit chance from 5% to 30%; unlocks automatically at Hunting League Rank / Prestige Level milestones, nothing consumed.\n• Category affinity: roll twice and keep the better for that stat family; requires Hunting League Rank 3, then register at the Sage with 250 Hunt Marks plus the category\'s signature NM trophy (consumed).\n• Critical augment: random per trade, chance scales with rank; puts every line at the top of your band.\n• Alternatively, spend a Maat\'s Cap (earned in Maat\'s Challenge) on a five-slot augment: all five lines come out perfect and the whole item is crystalized.\n• Absolute cap per slot at T5 with max rank, affinity and crit: (base + 31) × multiplier.' }, { title = 'Crystalization and scouring', note = '• Only a complete five-slot item with a max roll in every slot gets one crystalization roll; success locks all five lines (0x1F), failure locks none.\n• Crystalize chance: 5% at Sage rank 1 to 50% at rank 5; rank 0 cannot crystalize.\n• !augstats marks crystalized slots with *.\n• Maat\'s Cap is used only when you choose the Cap option on a five-slot Moogle augment or use !augment ... maat; carrying it does nothing.\n• Older partially crystalized items have the partial lock cleared on their next Moogle or !reroll use, keeping current values.\n• To wipe all augments (including crystalized), trade the gear alone to the Augment Moogle for 25,000 gil.' }, { title = '!reroll', note = '• !reroll keeps the augment types on an equipped item and re-rolls their values using the same tier, floor, affinity and crit rules; costs Infamy only, no gil or catalysts.\n• The Moogle replaces lines with the traded catalyst types; use it to change stats, use !reroll to improve numbers.\n• Both are capped at your tier band and never roll below band minimum + mastery rank.\n• Fully crystalized items cannot be rerolled; Maat\'s Cap does not work with !reroll.\n• Equip the item, then type !reroll <slot> (e.g. !reroll head) to preview ranges, floor, crit % and cost at no charge.\n• Type !reroll <slot> confirm to pay and re-roll all lines together, then re-equip to apply.\n• Slots: main sub ranged ammo head body hands legs feet neck waist ear1 ear2 ring1 ring2 back.\n• Infamy cost by tier: T1 50, T2 100, T3 200, T4 350, T5 500.\n• A crit on reroll makes the whole item perfect, which then gets its one crystalization roll.' }, { title = 'Tips and rules', note = '• Suggested stats: melee Attack and Accuracy; tanks HP, Defense, Phys DT / Phys DT II; casters Magic Accuracy / Magic Atk.\n• Max 5 catalysts per trade; catalysts are used up, gear is returned.\n• Re-augmenting overwrites an uncrystalized item\'s lines; a fully crystalized item stays locked until scoured.\n• Cancelling in the confirm menu returns everything.\n• Full catalyst list and values: Augment Moogle page; rank and affinity details: Augment Sage page.\n• Page last updated 2026-09-08.' } } },
    { name = 'The Weapon Journey', group = 'Custom', desc = 'Overview of the post-99 weapon progression order and the weapon-skill damage caps each stage unlocks. Source: https://ffxi-legendary.com/progression/weapon-journey/', steps = { { title = 'Route in order', note = '• At 99, claim free reforged armour with !shop reforge, use your Commemoration catalysts, and begin augmenting.\n• Complete an Ambuscade weapon; keep it, and get a separate matching Ajja later for Prime.\n• Forge a Relic, Empyrean and Mythic (parallel paths, each with its own guide); finishing all three unlocks Aeonics.\n• For an Aeonic: start its pilgrimage, do Geas Fete, defeat that weapon\'s solo Aeonic Maat, then complete the forge.\n• For Prime (final path): Ajja/Kaja stages from Ambuscade, the five Prime Trials, a matching Weapon Guardian, and the final Ragnarok clear.\n• Run !forgegates to list every current requirement before farming.' }, { title = 'Weapon-skill damage caps', note = '• iLvl 119 weapon: ordinary weapon skills cap at 79,999.\n• Final Ambuscade: 99,999; the weapon\'s linked native skill 149,999.\n• Final Relic / Empyrean / Mythic / Aeonic: native weapon skill up to 999,999.\n• Final Prime: native weapon skill 1,499,999–1,999,999 depending on job role.\n• Pet abilities (jug-pet Ready moves, Blood Pacts, automaton skills) have caps that rise with Ambuscade, REMA and matching Prime weapons; see Companion damage.' }, { title = 'Related guides', note = '• First 99 and first augments: The 1–99 Checklist.\n• Hallmarks and Ambuscade weapons: Ambuscade.\n• Relic Weapons, Empyrean Weapons, Mythic Weapons (incl. Ergon), Aeonic Weapons, Prime Weapons: first and repeat recipes.\n• All recipes: Weapon Forge; forge objectives: Weapon Pilgrimages.\n• Aeonic Maat Trials, Prime Weapon Trials, Prime Armory, Repeat Forges.\n• Page last updated 2026-08-27.' } } },
    { name = 'Weapon Pilgrimages', group = 'Custom', desc = 'Pilgrimages are the three-chapter objective sets required during each weapon forge, managed through the Weapon Forger. Source: https://ffxi-legendary.com/progression/weapon-pilgrimage/', steps = { { title = 'How pilgrimages work', note = '• Every weapon family has three chapters: equip the weapon stage the objective names, finish its fights, then go back to the Weapon Forger to continue forging.\n• Limit: two regular pilgrimages plus one Aeonic pilgrimage active at a time.\n• Relic: weapon-skill kills, named Unity NMs, Divergence Disjoined fights.\n• Empyrean: Abyssea weapon-skill objectives and signature material NMs.\n• Mythic: job-mastery objectives, Nyzul targets, Voidwatch fights.\n• Aeonic: weapon-skill kills on named Geas Fete Tier 3 and Tier 4 targets.\n• Prime: Elite and Geas Fete weapon-skill objectives.' }, { title = 'Starting and rules', note = '• Go to !hub, speak to the Weapon Forger, and pick Pilgrimages to see the chapter, target and required weapon stage.\n• Progress only counts under the conditions the objective lists; check it before swapping job or weapon.\n• Weapon skills are capped at 149,999 during pilgrimage battles.\n• Finishing a pilgrimage awards Reforge Marks, used in later forge steps including Prime.\n• Page last updated 2026-08-27.' } } },
    { name = 'Prime Weapon Trials', group = 'Custom', desc = 'The five trials required for a first Prime weapon, tracked at the Prime Armory, plus the final forge cost. Source: https://ffxi-legendary.com/progression/prime-trials/', steps = { { title = 'The gate', note = '• The final Prime forge needs all 5 Prime Weapon Trials, done in any order, plus the weapon\'s pilgrimage; then bring its Kaja stage to the Weapon Forger.\n• The trials do not replace the Prime pilgrimage or the final recipe.\n• Check progress and hand in collection trials at the Prime Armory NPC on Purgonorgo Isle (!hub).' }, { title = 'Trial 1: Abyssea collectibles', note = '• Collect 12 of each of the 20 Abyssea collectibles (240 total), which drop from Abyssea NMs.\n• Elements: Vision, Ardor, Wieldance, Balance, Voyage; each in Stone, Coin, Jewel and Card.\n• Turn in at the Prime Armory; only the full set is accepted and all of it is consumed at once.' }, { title = 'Trial 2: Endless Tower', note = '• Reach Endless Tower floor 50; the trial completes automatically.' }, { title = 'Trial 3: Prime Voucher', note = '• Obtain one Prime Voucher (Maze Monger Crown): ~1% from Hunting League NMs or 0.5% from the custom Maat fight.\n• Hand it in at the Prime Armory; it no longer drops after Trial 3 is done.' }, { title = 'Trial 4: Weapon Guardian', note = '• Defeat any Weapon Guardian, the boss summoned by mastering a job at the end of the Job Mastery path.\n• A Guardian of the matching family is needed at the forge.' }, { title = 'Trial 5: Dynamis currencies', note = '• Hand in 99 Lungo-Nango Jadeshell, 99 Montiont Silverpiece and 99 100 Byne Bill (297 total) in one trade at the Prime Armory.\n• Keep each as a single 99 stack in main inventory.' }, { title = 'Final forge', note = '• With all five trials complete, the pilgrimage done and other gates met, bring the chosen Kaja weapon to the Weapon Forger.\n• Recipe: 100 Demons Medals, 5,000 Reforge Marks, 750,000,000 gil.\n• Check the Prime Weapons guide first.\n• Page last updated 2026-09-07.' } } },
}

return S
